#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/rand.h>

#define MAX_TOKEN_LEN 512
#define MAX_FIELD_LEN 128
#define HMAC_LEN 32
#define TIMESTAMP_WINDOW 300

static const unsigned char SECRET_KEY[32] = {
    0x4a, 0x7b, 0x3c, 0x9d, 0x2e, 0x1f, 0x5a, 0x6b,
    0x8c, 0x0d, 0x4e, 0x7f, 0x3a, 0x9b, 0x2c, 0x1d,
    0x5e, 0x6f, 0x8a, 0x0b, 0x4c, 0x7d, 0x3e, 0x9f,
    0x2a, 0x1b, 0x5c, 0x6d, 0x8e, 0x0f, 0x4a, 0x7b
};

typedef struct {
    char username[MAX_FIELD_LEN];
    char role[MAX_FIELD_LEN];
    int64_t issued_at;
    int64_t expires_at;
    unsigned char signature[HMAC_LEN];
    unsigned int sig_len;
} AuthToken;

/* Sanitize field: remove control chars, enforce length */
static int sanitize_field(const char *input, char *output, size_t max_len) {
    size_t i, j = 0;
    if (!input || !output) return -1;
    for (i = 0; input[i] && j < max_len - 1; i++) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 0x20 && c <= 0x7E && c != '|' && c != '\\') {
            output[j++] = (char)c;
        }
    }
    output[j] = '\0';
    return (j > 0) ? 0 : -1;
}

/* Compute HMAC-SHA256 over the token payload */
static int compute_hmac(const char *payload, size_t payload_len,
                        unsigned char *out, unsigned int *out_len) {
    unsigned char *result = HMAC(EVP_sha256(), SECRET_KEY, sizeof(SECRET_KEY),
                                 (unsigned char *)payload, payload_len,
                                 out, out_len);
    return result ? 0 : -1;
}

/* Serialize token fields into pipe-delimited payload */
static int serialize_payload(const AuthToken *tok, char *buf, size_t buf_len) {
    int written = snprintf(buf, buf_len, "%s|%s|%lld|%lld",
                           tok->username, tok->role,
                           (long long)tok->issued_at,
                           (long long)tok->expires_at);
    if (written < 0 || (size_t)written >= buf_len) return -1;
    return written;
}

/* Create a signed auth token */
int create_token(const char *username, const char *role, AuthToken *tok) {
    char payload[MAX_TOKEN_LEN];
    int payload_len;

    memset(tok, 0, sizeof(AuthToken));

    if (sanitize_field(username, tok->username, MAX_FIELD_LEN) != 0) return -1;
    if (sanitize_field(role, tok->role, MAX_FIELD_LEN) != 0) return -1;

    tok->issued_at = (int64_t)time(NULL);
    tok->expires_at = tok->issued_at + 3600; /* 1 hour */

    payload_len = serialize_payload(tok, payload, sizeof(payload));
    if (payload_len < 0) return -1;

    if (compute_hmac(payload, (size_t)payload_len, tok->signature, &tok->sig_len) != 0)
        return -1;

    return 0;
}

/* Constant-time comparison to prevent timing attacks */
static int secure_compare(const unsigned char *a, const unsigned char *b, size_t len) {
    /* Compare len bytes; return 0 if equal */
    volatile unsigned char result = 0;
    size_t i;
    for (i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return (int)result;
}

/* Verify token signature and expiration */
int verify_token(const AuthToken *tok) {
    char payload[MAX_TOKEN_LEN];
    unsigned char expected_sig[HMAC_LEN];
    unsigned int expected_len = 0;
    int payload_len;

    /* Check timestamp validity */
    int64_t now = (int64_t)time(NULL);
    if (tok->issued_at > now + TIMESTAMP_WINDOW) return -1; /* future token */
    if (tok->expires_at < now) return -1; /* expired */

    /* Recompute expected signature */
    payload_len = serialize_payload(tok, payload, sizeof(payload));
    if (payload_len < 0) return -1;

    if (compute_hmac(payload, (size_t)payload_len, expected_sig, &expected_len) != 0)
        return -1;

    /* Verify signature length matches */
    if (tok->sig_len != expected_len) return -1;

    /* Constant-time signature comparison with fixed length */
    if (secure_compare(expected_sig, tok->signature, HMAC_LEN) != 0)
        return -1;

    return 0;
}

/* Check if user has admin privileges */
int check_admin(const AuthToken *tok) {
    if (verify_token(tok) != 0) return 0;
    return (strcmp(tok->role, "admin") == 0);
}

/* Parse a token from wire format: username|role|issued_at|expires_at|hex_signature */
int parse_token_from_wire(const char *wire, AuthToken *tok) {
    char buf[MAX_TOKEN_LEN];
    char *fields[5];
    int field_count = 0;
    char *ptr, *start;

    if (!wire || !tok || strlen(wire) >= MAX_TOKEN_LEN) return -1;

    memset(tok, 0, sizeof(AuthToken));
    strncpy(buf, wire, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    /* Split on pipe delimiter */
    start = buf;
    for (ptr = buf; *ptr && field_count < 5; ptr++) {
        if (*ptr == '|') {
            *ptr = '\0';
            fields[field_count++] = start;
            start = ptr + 1;
        }
    }
    if (field_count < 4) return -1;
    fields[field_count++] = start;

    if (field_count != 5) return -1;

    /* Copy and sanitize username/role */
    if (sanitize_field(fields[0], tok->username, MAX_FIELD_LEN) != 0) return -1;
    if (sanitize_field(fields[1], tok->role, MAX_FIELD_LEN) != 0) return -1;

    /* Parse timestamps */
    tok->issued_at = strtoll(fields[2], NULL, 10);
    tok->expires_at = strtoll(fields[3], NULL, 10);

    /* Parse hex signature */
    size_t hex_len = strlen(fields[4]);
    if (hex_len != HMAC_LEN * 2) return -1;

    for (size_t i = 0; i < HMAC_LEN; i++) {
        unsigned int byte_val;
        if (sscanf(fields[4] + i * 2, "%2x", &byte_val) != 1) return -1;
        tok->signature[i] = (unsigned char)byte_val;
    }
    tok->sig_len = HMAC_LEN;

    return 0;
}

/* Elevated operation requiring admin */
int perform_admin_action(const char *wire_token, const char *action) {
    AuthToken tok;

    if (!wire_token || !action) return -1;
    if (parse_token_from_wire(wire_token, &tok) != 0) {
        fprintf(stderr, "Token parse failed\n");
        return -1;
    }

    if (!check_admin(&tok)) {
        fprintf(stderr, "Access denied: not admin\n");
        return -1;
    }

    printf("Admin action performed: %s by %s\n", action, tok.username);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <wire_token> <action>\n", argv[0]);
        return 1;
    }
    return perform_admin_action(argv[1], argv[2]);
}
